// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { Btn, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, DUPLICATE_OF, LIST, SHUFFLED, SORTED, UNIQUE } from './script'

const ROW = 27

const build: Build = ({ tl, qa, step, final, move, click, count, wait, cursorOut }) => {
  const rows = qa('row')
  const place = (order: number[], at?: gsap.Position) => {
    tl.to(
      order.map((index) => rows[index]),
      { y: (slot) => slot * ROW, duration: 0.7, ease: 'expo.inOut', stagger: 0.03 },
      at,
    )
  }
  rows.forEach((row, index) => tl.set(row, { y: index * ROW }, 0))

  step(0)
  tl.fromTo(rows, { opacity: 0, x: -12 }, { opacity: 1, x: 0, duration: 0.35, stagger: 0.06 }, 0.3)
  count('lines', LIST.length, { at: '<', duration: 0.6 })

  step(1, '+=0.4')
  move('dedupe')
  click('dedupe')
  DUPLICATE_OF.forEach((first, index) => {
    if (first === -1) return
    tl.to(rows[index], { backgroundColor: 'rgba(251,113,133,0.18)', duration: 0.2 }, '<')
    tl.to(
      rows[index],
      { y: first * ROW, opacity: 0, scale: 0.96, duration: 0.6, ease: 'power3.inOut' },
      '<0.15',
    )
  })
  place(UNIQUE, '-=0.2')
  count('lines', UNIQUE.length, { at: '<', from: LIST.length, duration: 0.5 })

  step(2, '+=0.4')
  move('sort')
  click('sort')
  place(SORTED, '<0.1')

  step(3, '+=0.5')
  move('shuffle')
  click('shuffle')
  place(SHUFFLED, '<0.1')
  move('number', { at: '+=0.2' })
  click('number')
  tl.fromTo(
    qa('num'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.3, stagger: 0.05 },
    '<',
  )
  tl.to(rows, { x: 22, duration: 0.4, ease: 'power3.out' }, '<')
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Line Tools deduping, sorting, shuffling and numbering a list of emails"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome
        aside={
          <span className="font-mono text-[10px] text-muted">
            <span data-d="lines" className="text-ink">
              0
            </span>{' '}
            lines
          </span>
        }
      >
        <div className="flex h-full flex-col gap-3">
          <div className="relative min-h-0 flex-1 overflow-hidden rounded-xl border border-line bg-canvas/80 p-3 font-mono text-[11.5px]">
            <div className="relative">
              {UNIQUE.map((_, slot) => (
                <span
                  key={slot}
                  data-d="num"
                  className="absolute left-0 flex h-[25px] w-4 items-center text-muted opacity-0"
                  style={{ top: slot * ROW }}
                >
                  {slot + 1}
                </span>
              ))}
              {LIST.map((item, index) => (
                <p
                  key={index}
                  data-d="row"
                  className="absolute inset-x-0 top-0 flex h-[25px] items-center rounded-md px-2 text-ink-soft"
                >
                  {item}
                </p>
              ))}
            </div>
          </div>
          <div className="flex flex-wrap gap-1.5">
            <Btn d="dedupe">Dedupe</Btn>
            <Btn d="sort">Sort</Btn>
            <Btn d="shuffle">Shuffle</Btn>
            <Btn d="number">Numbering</Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
